import{_ as t,o as r,c as n,a2 as o}from"./chunks/framework.BWuWLRhz.js";const g=JSON.parse('{"title":"Index","description":"","frontmatter":{},"headers":[],"relativePath":"user-guide/settings/index-drives.md","filePath":"user-guide/settings/index-drives.md","lastUpdated":1785993908000}'),s={name:"user-guide/settings/index-drives.md"};function a(i,e,l,d,c,u){return r(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="index" tabindex="-1">Index <a class="header-anchor" href="#index" aria-label="Permalink to &quot;Index&quot;">​</a></h1><p>Five tabs, in order: <strong>Local Drives</strong>, <strong>Network Drives</strong>, <strong>WSL</strong> (only shown once a distribution is detected), <strong>Folders</strong>, and <strong>Exclusion Rules</strong>.</p><h2 id="local-drives" tabindex="-1">Local Drives <a class="header-anchor" href="#local-drives" aria-label="Permalink to &quot;Local Drives&quot;">​</a></h2><ul><li>Status card summarizing how many drives and items are indexed, plus a <strong>Rebuild Index</strong> button for a full re-scan.</li><li>One row per local drive: an <strong>enable/disable checkbox</strong>, drive name, file system (NTFS/ReFS/...), current status, indexed item count, and a per-row <strong>Rebuild</strong>/<strong>Remove</strong> action — plus a <strong>Stop</strong> action while a rebuild is running, for every drive except true NTFS (its scan has no safe point to interrupt).</li><li>NTFS and ReFS drives track changes continuously through the Windows USN Journal; other local file systems (FAT32, exFAT, ...) have no journal to read, so they&#39;re watched for changes directly instead. Either way, a manual rebuild is rarely needed, but is there if something looks out of sync — and if one gets interrupted (stopped, or the app/service restarts mid-scan), the next rebuild picks up from where it left off instead of starting over.</li></ul><p>Searching keeps working while a rebuild is running. The drive being rebuilt goes on answering from its previous index until the new one is ready, and the other drives are unaffected — a rebuild never leaves you with an empty result list.</p><h2 id="network-drives" tabindex="-1">Network Drives <a class="header-anchor" href="#network-drives" aria-label="Permalink to &quot;Network Drives&quot;">​</a></h2><ul><li>Same status card and <strong>Rebuild Index</strong> button as Local Drives.</li><li>One row per mapped network drive: enable checkbox, path/name, status (Indexing / Ready / Cached / Failed / Pending / Connected), item count, and a <strong>Refresh Mode</strong> dropdown: <ul><li><strong>Manual</strong> — only refreshes on demand (via Rebuild Index).</li><li><strong>Every 15 minutes</strong></li><li><strong>Every hour</strong></li><li><strong>Daily</strong></li></ul></li></ul><p>Network shares don&#39;t expose a change journal the way local NTFS volumes do, which is why they&#39;re refreshed on a schedule instead of in real time. The scanning engine includes built-in branch path tracking and symlink loop detection, automatically intercepting recursion loops on NAS/SMB shares even if symlinks point back to ancestor directories.</p><h2 id="wsl" tabindex="-1">WSL <a class="header-anchor" href="#wsl" aria-label="Permalink to &quot;WSL&quot;">​</a></h2><p>Only shown once at least one WSL distribution is detected — same shape as Network Drives (status card, <strong>Rebuild Index</strong> button, and one row per distribution with status/item count/<strong>Refresh Mode</strong>). Distributions are detected automatically; there&#39;s no manual &quot;add&quot; step.</p><h2 id="folders" tabindex="-1">Folders <a class="header-anchor" href="#folders" aria-label="Permalink to &quot;Folders&quot;">​</a></h2><p>Index arbitrary individual folders instead of a whole drive or share — useful for indexing just one subtree without pulling in everything else on that volume.</p><ul><li>An <strong>Add Folder</strong> button opens a folder picker; a <strong>Rebuild Index</strong> button re-scans every folder in the list.</li><li>One row per added folder: enable checkbox, path, status, item count, and the same <strong>Refresh Mode</strong> dropdown (Manual / Every 15 minutes / Every hour / Daily) as network drives — folders are scanned on a schedule rather than tracked continuously, the same way network shares are.</li><li>The folder picker also accepts a <strong>UNC network share path</strong> (e.g. <code>\\\\server\\share</code>, or a subfolder inside it) browsed to via <em>Network</em> in the picker — useful for indexing a single share or subtree without adding the whole server as a mapped network drive.</li></ul><h2 id="exclusion-rules" tabindex="-1">Exclusion Rules <a class="header-anchor" href="#exclusion-rules" aria-label="Permalink to &quot;Exclusion Rules&quot;">​</a></h2><p>Three sub-tabs, each with the same shape: a single-entry textbox + <strong>Add</strong> button, a list of existing rules (each editable/deletable), and a bulk multi-line textbox with <strong>Generate from List</strong> / <strong>Apply to List</strong> buttons for editing everything at once.</p><ul><li><strong>Path Exclusions</strong> — full paths or environment variables (e.g. <code>D:\\Cache</code>, <code>%ProgramData%</code>).</li><li><strong>Glob Wildcards</strong> — <code>*</code> (any characters in a filename), <code>?</code> (single character), <code>**</code> (recursive directories). Examples: <code>*.tmp</code>, <code>**/node_modules/**</code>, <code>bin/**</code>.</li><li><strong>Regex Patterns</strong> — arbitrary regular expressions matched against the path/filename (partial match). Examples: <code>^\\.</code> (hidden files), <code>~$</code> (Office temp files), <code>\\.git\\</code>.</li></ul><p>Exclusions apply to local, network, and folder indexing alike, and network drives/folders re-scan automatically after you apply exclusion changes.</p>',17)])])}const p=t(s,[["render",a]]);export{g as __pageData,p as default};
